import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第五十二卦 艮 艮為山 艮上艮下","description":"周易 - 第五十二卦 艮 艮為山 艮上艮下","frontmatter":{"title":"第五十二卦 艮 艮為山 艮上艮下","description":"周易 - 第五十二卦 艮 艮為山 艮上艮下"},"headers":[],"relativePath":"classics/zhouyi/053.md","filePath":"classics/zhouyi/053.md"}'),l={name:"classics/zhouyi/053.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="艮" tabindex="-1">艮 <a class="header-anchor" href="#艮" aria-label="Permalink to “艮”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>艮其背，不獲其身，行其庭，不見其人，無咎。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>艮，止也。時止則止，時行則行，動靜不失其時，其道光明。艮其止，止其所也。上下敵應，不相與也。是以不獲其身，行其庭不見其人，無咎也。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>兼山，艮；君子以思不出其位。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>艮其趾，無咎，利永貞。象曰：艮其趾， 未失正也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>艮其腓，不拯其隨，其心不快。象曰：不拯其隨，未退聽也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>艮其限，列其夤，厲薰心。象曰：艮其限，危薰心也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>艮其身，無咎。象曰：艮其身，止諸躬也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>艮其輔，言有序，悔亡。象曰：艮其輔，以中正也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>敦艮，吉。象曰：敦艮之吉，以厚終也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
